#!/usr/bin/env python3
"""Relay for the QEMU VM serial console.

- Connects to the QEMU serial unix socket.
- Logs all console output to vm-console.log
- Forwards lines written to vm-input.fifo to the VM console.

Usage to send a command to the VM:
    echo 'my command' >> vm-input.fifo
"""
import socket
import os
import threading
import time

BASE = os.path.dirname(os.path.abspath(__file__))
SOCK = os.path.join(BASE, 'vm-serial.sock')
LOG = os.path.join(BASE, 'vm-console.log')
FIFO = os.path.join(BASE, 'vm-input.fifo')

if not os.path.exists(FIFO):
    try:
        os.mkfifo(FIFO)
    except FileExistsError:
        pass

s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
s.connect(SOCK)

logf = open(LOG, 'ab', buffering=0)


def reader():
    try:
        while True:
            data = s.recv(65536)
            if not data:
                break
            logf.write(data)
    except OSError:
        pass


t = threading.Thread(target=reader, daemon=True)
t.start()

